<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';require_once __DIR__.'/read-model.php';require_once __DIR__.'/vehicle-store.php';
function kalite_filo_admin_featured_path():string{return (string)kalite_filo_admin_config()['data_root'].DIRECTORY_SEPARATOR.'drafts'.DIRECTORY_SEPARATOR.'featured-vehicles.json';}
/** @param list<array<string,mixed>> $records @return list<string> */
function kalite_filo_admin_featured_ids(array $records):array{$path=kalite_filo_admin_featured_path();if(is_file($path)){$raw=json_decode((string)file_get_contents($path),true,6,JSON_THROW_ON_ERROR);if(is_array($raw)&&is_array($raw['ids']??null))return array_values($raw['ids']);}return array_values(array_map(fn($v)=>(string)$v['id'],array_filter($records,fn($v)=>($v['featured']??false)===true)));}
try{kalite_filo_admin_start_session();kalite_filo_admin_require_authentication();$records=kalite_filo_admin_vehicle_records();if(($_SERVER['REQUEST_METHOD']??'')==='GET')kalite_filo_admin_json(['ids'=>kalite_filo_admin_featured_ids($records),'vehicles'=>$records]);kalite_filo_admin_require_method('POST');kalite_filo_admin_require_same_origin();kalite_filo_admin_require_csrf();$body=kalite_filo_admin_read_json();$ids=$body['ids']??null;if(!is_array($ids)||count($ids)!==4||count(array_unique($ids))!==4)throw new InvalidArgumentException('featured_requires_four');$byId=[];foreach($records as $record)$byId[(string)$record['id']]=$record;foreach($ids as $id){$vehicle=$byId[$id]??null;if(!is_array($vehicle)||($vehicle['publicationStatus']??'')!=='published'||(!is_array($vehicle['coverImage']??null)&&!is_array($vehicle['draftMedia']??null)))throw new InvalidArgumentException('featured_vehicle_ineligible');}foreach($records as &$record)$record['featured']=in_array($record['id'],$ids,true);unset($record);$path=kalite_filo_admin_featured_path();kalite_filo_admin_ensure_private_directory(dirname($path));$tmp=$path.'.tmp-'.bin2hex(random_bytes(5));file_put_contents($tmp,json_encode(['schemaVersion'=>1,'ids'=>array_values($ids),'updatedAt'=>gmdate('c'),'updatedBy'=>$_SESSION['identity']['id']],JSON_THROW_ON_ERROR|JSON_PRETTY_PRINT),LOCK_EX);@chmod($tmp,0600);if(!rename($tmp,$path)){@unlink($tmp);throw new RuntimeException('Featured store could not be replaced.');}kalite_filo_admin_write_vehicle_records($records);kalite_filo_admin_audit('featured_vehicle_change','success',['ids'=>$ids]);kalite_filo_admin_json(['ids'=>$ids]);}catch(InvalidArgumentException $e){kalite_filo_admin_json(['error'=>$e->getMessage()],422);}catch(Throwable $e){error_log('Featured vehicles failed: '.$e->getMessage());kalite_filo_admin_json(['error'=>'service_unavailable'],503);}
